def solution(*args, **kwargs):
    # Determine input source:
    # - If called with a string argument (as in tests), use that.
    # - Otherwise, read from stdin (for normal usage).
    if args and isinstance(args[0], str):
        s = args[0].rstrip('\n')
    else:
        import sys
        s = sys.stdin.readline().rstrip('\n')

    count = 0
    open_count = 0

    for ch in s:
        if ch == '[':
            open_count += 1
        elif ch == ']':
            if open_count > 0:
                count += 1
                open_count -= 1

    if count == 0:
        result = -1
    else:
        result = count

    # Print result for standard usage
    if not args:
        print(result)

    return result
